<script setup>
import { getMigrateProgress } from '@/services'
import RadialProgress from 'vue3-radial-progress'

const progress = reactive({
  knowledge: {
    // 知识库
    status: 'MOVING', // 状态，同上面的状态
    message: '', // 如果是FAILED,则此处为失败信息描述
    total: 0, // 总数
    moved: 0 // 迁移数量
  },
  model: {
    status: 'MOVING',
    message: '',
    total: 0,
    moved: 0
  }
})

let timer

function getProgress() {
  clearTimeout(timer)
  timer = null
  return getMigrateProgress().then(({ resData }) => {
    progress.knowledge = resData.knowledge
    progress.model = resData.model
    if (progress.knowledge.status !== 'MOVING' && progress.model.status !== 'MOVING') {
      clearTimeout(timer)
      timer = null
      return
    }
    timer = setTimeout(() => {
      getProgress()
    }, 3000)
  })
}

getProgress()

const colorMap = {
  SUCCESS: { start: '#67e8f9', stop: '#00E0A1' },
  FAILED: { start: '#f97316', stop: '#dc2626' },
  MOVING: { start: '#d97706', stop: '#1d4ed8' },
  NOT_MOVED: { start: '#67e8f9', stop: '#00E0A1' }
}
const dialogRef = inject('dialogRef')

function close() {
  dialogRef.value.close()
}
</script>

<template>
  <div class="flex flex-col items-center justify-center">
    <div class="flex items-center justify-center gap-12 p-10 pt-4">
      <div class="model flex flex-col items-center justify-start">
        <div class="w-18 shrink-0 grow-0 font-bold text-lg mb-4">{{ $t('lang.model') }}</div>
        <RadialProgress
          :diameter="150"
          :completed-steps="progress.model.moved"
          :total-steps="progress.model.total"
          :start-color="colorMap[progress.model.status]?.start"
          :stop-color="colorMap[progress.model.status]?.stop"
        >
          <div class="">
            <span v-if="progress.model.status === 'MOVING'"> {{ progress.model.moved }} / {{ progress.model.total }} </span>
            <span
              class="text-sm font-semibold text-primary-400"
              v-else-if="progress.model.status === 'SUCCESS' || progress.model.status === 'NOT_MOVED'"
            >
              {{ progress.model.status }}
            </span>
            <span class="text-sm font-semibold text-red-500" v-else-if="progress.model.status === 'FAILED'">
              {{ progress.model.status }}
              <i v-if="progress.model.message" v-tooltip="progress.model.message" class="pi pi-question-circle ml-2"></i>
            </span>
          </div>
        </RadialProgress>
      </div>
      <div class="knowledge flex flex-col items-center justify-start">
        <div class="w-18 shrink-0 grow-0 font-bold text-lg mb-4">{{ $t('kb.knowledgeBase') }}</div>
        <RadialProgress
          :diameter="150"
          :completed-steps="progress.knowledge.moved"
          :total-steps="progress.knowledge.total"
          :start-color="colorMap[progress.knowledge.status].start"
          :stop-color="colorMap[progress.knowledge.status].stop"
        >
          <div class="">
            <span v-if="progress.knowledge.status === 'MOVING'"> {{ progress.knowledge.moved }} / {{ progress.knowledge.total }} </span>
            <span class="text-sm font-semibold text-primary-400" v-else-if="progress.knowledge.status === 'SUCCESS'">
              {{ progress.knowledge.status }}
            </span>
            <span class="text-sm font-semibold text-red-500" v-else-if="progress.knowledge.status === 'FAILED'">
              {{ progress.knowledge.status }}
              <i v-if="progress.knowledge.message" v-tooltip="progress.knowledge.message" class="pi pi-question-circle ml-2"></i>
            </span>
          </div>
        </RadialProgress>
      </div>
    </div>
    <Button
      v-if="progress.knowledge.status !== 'MOVING' && progress.model.status !== 'MOVING'"
      class="self-end"
      severity="secondary"
      @click="close"
      >关闭
    </Button>
  </div>
</template>

<style scoped lang="scss"></style>
